mapper.select:
select id, prj_id prjId, name, start_date startDate, end_date endDate
  from milestone
 where id = #{id}

SELECT COUNT(*)
  FROM milestone_timeline
 WHERE milestone_issue_id = #{milestoneIssueId}

select id,subject from issue
where id not in(
	select issue_id from milestone_issue
)
and prj_id = #{id}
order by id

mapper.update:
update milestone
set name=#{name}, start_date=#{startDate, jdbcType=DATE}, end_date=#{endDate, jdbcType=DATE}
where id=#{id}

mapper.select:
select avg(done_ratio) from issue where id in(
	select issue_id from milestone_issue 
	where milestone_id=${id}
)

mapper.update:
update milestone_issue
set milestone_id = #{milestoneId}
where id = #{id}

update milestone_timeline
set contents = #{contents},
entry_date = #{entryDate},
type_cd = #{typeCd}
where id = #{id}
